import React, { useState, useEffect } from 'react';
import { getAllExamCounts } from '../services/api';

const ExamDataCount = ({ franchiseId }) => {
    const [examDataCount, setExamDataCount] = useState(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [selectedDate, setSelectedDate] = useState('');
    const [selectedDateCount, setSelectedDateCount] = useState(null);

    // Function to fetch exam data count
    const fetchExamDataCount = async (date = null) => {
        setLoading(true);
        setError('');
        try {
            const response = await getAllExamCounts(franchiseId, date);

            if (!response) {
                throw new Error('Invalid API response');
            }

            if (date) {
                setSelectedDateCount(response.examsByDay || 'No data');
            } else {
                setExamDataCount({
                    examsByDay: response.examsByDay || 0,
                    examsByWeek: response.examsByWeek || 0,
                    examsByMonth: response.examsByMonth || 0,
                });
            }
        } catch (err) {
            console.error('Error fetching data:', err);
            setError('An error occurred while fetching exam data.');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        if (franchiseId) {
            fetchExamDataCount();
        }
    }, [franchiseId]);

    useEffect(() => {
        if (selectedDate) {
            fetchExamDataCount(selectedDate);
        }
    }, [selectedDate]);

    return (
        <div>
            <h2>Exam Data Count for Franchise {franchiseId}</h2>

            <div style={{ marginBottom: '20px' }}>
                <label htmlFor="datePicker" style={{ marginRight: '10px', fontWeight: 'bold' }}>
                    Select Date:
                </label>
                <input
                    id="datePicker"
                    type="date"
                    value={selectedDate}
                    onChange={(e) => setSelectedDate(e.target.value)}
                    disabled={loading}
                />
            </div>

            {error && <p style={{ color: 'red' }}>{error}</p>}

            {loading && <p>Loading...</p>}

            {selectedDate && selectedDateCount !== null && (
                <div style={{ marginBottom: '20px', fontSize: '16px', color: '#333' }}>
                    <p>
                        Exam count for <strong>{selectedDate}</strong>: <strong>{selectedDateCount}</strong>
                    </p>
                </div>
            )}

            {examDataCount && (
                <div
                    style={{
                        display: 'flex',
                        justifyContent: 'space-between',
                        marginTop: '20px',
                        gap: '10px',
                        flexWrap: 'wrap',
                    }}
                >
                    <div
                        style={{
                            width: '20%',
                            padding: '8px',
                            border: '1px solid #ccc',
                            borderRadius: '8px',
                            textAlign: 'center',
                            backgroundColor: '#f1f1f1',
                            boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
                        }}
                    >
                        <h3 style={{ color: '#333', fontSize: '14px' }}>Today</h3>
                        <p style={{ color: '#555', fontSize: '16px' }}>
                            {examDataCount.examsByDay}
                        </p>
                    </div>

                    <div
                        style={{
                            width: '20%',
                            padding: '8px',
                            border: '1px solid #ccc',
                            borderRadius: '8px',
                            textAlign: 'center',
                            backgroundColor: '#e0f7fa',
                            boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
                        }}
                    >
                        <h3 style={{ color: '#00796b', fontSize: '14px' }}>Week</h3>
                        <p style={{ color: '#004d40', fontSize: '16px' }}>
                            {examDataCount.examsByWeek}
                        </p>
                    </div>

                    <div
                        style={{
                            width: '20%',
                            padding: '8px',
                            border: '1px solid #ccc',
                            borderRadius: '8px',
                            textAlign: 'center',
                            backgroundColor: '#fff3e0',
                            boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
                        }}
                    >
                        <h3 style={{ color: '#f57c00', fontSize: '14px' }}>Month</h3>
                        <p style={{ color: '#e65100', fontSize: '16px' }}>
                            {examDataCount.examsByMonth}
                        </p>
                    </div>
                </div>
            )}
        </div>
    );
};

export default ExamDataCount;
